import Avatar from "../components/Avatar";

function Cliente() {
  return (
    <div>
      <h2>Opiniones de Clientes</h2>

      <Avatar />
      <h3>María López</h3>
      <p>Excelente atención y entrega rápida.</p>

      <hr />

      <Avatar />
      <h3>Carlos Pérez</h3>
      <p>Los productos llegaron en buen estado y a tiempo.</p>
    </div>
  );
}

export default Cliente;
